// Citations (D168/D172): every `modules/`, `tests/Modules` and `app/Config` path below is read at
// `5d65939e^`, the last commit before the PHP app was retired.
//
// The permission matrix (plan §5 S1.3, increment 2b): v3's list, the built-in roles' permissions and
// what the guest role can never have.
//
// The oracle is `test/fixtures/php-permissions.json`, generated by `scripts/gen-permissions-fixture.sh`
// from `modules/Auth/Permissions.php` and `modules/Auth/RoleAdmin.php` — the same two files v3 reads
// when it renders the roles editor. `src/auth/permissions.ts` spells these lists by hand, and the page
// shows them and the handlers write them into the roles table, so a typo would grant or withhold a
// permission silently. This is the test that makes that impossible without a red run.
//
// The route-level matrix is not here: `test/http/routes-parity.spec.ts` compares each route's
// `permission` column against `php-routes.json`, which is G1's route-for-route assertion.

import { describe, expect, it } from "vitest";
import { ALL, NOT_FOR_GUESTS, ROLE_DEFAULTS } from "../../src/auth/permissions";
import fixture from "../fixtures/php-permissions.json";

describe("the permission matrix", () => {
	it("is v3's list, in v3's order, with v3's labels and hints", () => {
		expect(ALL.map(([key, label, hint]) => [key, label, hint])).toEqual(fixture.all);
	});

	it("gives the built-in roles v3's permission sets, in v3's order", () => {
		expect(ROLE_DEFAULTS.map(([key, name, perms]) => [key, name, [...perms]])).toEqual(fixture.roleDefaults);
	});

	it("holds back from the guest role exactly what v3 holds back", () => {
		expect([...NOT_FOR_GUESTS]).toEqual(fixture.notForGuests);
	});
});
